"""SSRF protection and private IP subnet filter."""

import ipaddress
import socket
from url_parser import ParsedURL, parse_url


FORBIDDEN_HOSTNAMES = {"localhost", "metadata.google.internal", "instance-data"}


class SSRFGuard:
    def __init__(self, allowed_schemes: set[str] = None):
        self.allowed_schemes = allowed_schemes or {"http", "https"}

    def is_safe_url(self, raw_url: str) -> bool:
        parsed = parse_url(raw_url)
        if not parsed:
            return False
        if parsed.scheme not in self.allowed_schemes:
            return False
        if parsed.host in FORBIDDEN_HOSTNAMES:
            return False

        # Resolve and check IP address against private/loopback/link-local ranges
        try:
            ip = ipaddress.ip_address(parsed.host)
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved:
                return False
        except ValueError:
            # If hostname is a numeric string (e.g. decimal IP 2130706433), parse as integer IP
            if parsed.host.isdigit():
                try:
                    ip = ipaddress.ip_address(int(parsed.host))
                    if ip.is_private or ip.is_loopback or ip.is_link_local:
                        return False
                except Exception:
                    return False
        return True
